    question: "What is the ROC-AUC metric, and when is it not a good choice for evaluating a classifier?",
    slug: "22-what-is-the-roc-auc-metric-and-when-is-it-not-a-good-choice-for-evaluating-a-classifier",
    categoryName: "Core Machine Learning",
    categorySlug: "data-science/core-machine-learning",
